def handle(app, svc):
    resp = svc.apply(app)

    # API v2 format: {"api_version": 2, "result": {"outcome": ..., "credit_limit": ...}}
    outcome = resp["result"]["outcome"]
    credit_limit = resp["result"]["credit_limit"]

    # Network referral rule (spec section 4):
    # self_employed applicant with requested_limit above 6000 -> queue_review
    # A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 6000
            and outcome != "declined"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    else:  # manual_review
        return {"action": "queue_review", "limit": 0}

